# Stage A feature extraction for CCD and DoTA. Generated by kaggle/build_extract.py from commit 6543fce.
import base64, glob, io, json, os, shutil, subprocess, sys, time, zipfile
CODE = "/kaggle/tmp/code"
os.makedirs(CODE, exist_ok=True)
zipfile.ZipFile(io.BytesIO(base64.b64decode(""))).extractall(CODE)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "ultralytics"], check=True)
OUT = "/kaggle/working/features"
os.makedirs(OUT, exist_ok=True)
T0 = time.time()

def find(pattern):
    hits = glob.glob(pattern, recursive=True)
    return hits[0] if hits else None

ccd = find("/kaggle/input/**/CCD/videos")
dota = find("/kaggle/input/**/DoTA_STAGNet/videos")
assert ccd and dota, ("inputs missing", ccd, dota)
items = []
for p in sorted(glob.glob(ccd + "/Crash-1500/*.mp4")): items.append(("ccd_pos_" + os.path.basename(p)[:-4], p))
for p in sorted(glob.glob(ccd + "/Normal/*.mp4")): items.append(("ccd_neg_" + os.path.basename(p)[:-4], p))
for p in sorted(glob.glob(dota + "/*/positive/*.avi")): items.append(("dota_pos_" + os.path.basename(p)[:-4], p))
for p in sorted(glob.glob(dota + "/*/negative/*.avi")): items.append(("dota_neg_" + os.path.basename(p)[:-4], p))
print("videos:", len(items), flush=True)
assert len(items) == 4500 + 1490, len(items)
# resume: reuse features from an attached earlier run
for p in glob.glob("/kaggle/input/**/features/*.npz", recursive=True):
    d = os.path.join(OUT, os.path.basename(p))
    if not os.path.exists(d):
        shutil.copy(p, d)
open("/kaggle/tmp/all.txt", "w").write("\n".join(f"{v} {p}" for v, p in items))

# models downloaded once, before workers start
os.chdir(CODE)
from ultralytics import YOLO
YOLO("yolo11m.pt")
from transformers import AutoModel, SegformerForSemanticSegmentation
SegformerForSemanticSegmentation.from_pretrained("nvidia/segformer-b2-finetuned-cityscapes-1024-1024")
AutoModel.from_pretrained("facebook/dinov2-small")
import torch, numpy as np
ngpu = max(1, torch.cuda.device_count())
env = dict(os.environ, PYTHONPATH=CODE)

def run(listfile, shard, nshard, gpu, logf):
    return subprocess.Popen([sys.executable, "-u", "-m", "src.features.extract", "--videos", listfile, "--out", OUT,
                             "--shard", str(shard), "--num_shards", str(nshard), "--cfg", json.dumps({"TIME_BUDGET_H": 7.3})],
                            cwd=CODE, env=dict(env, CUDA_VISIBLE_DEVICES=str(gpu)), stdout=open(logf, "w"), stderr=subprocess.STDOUT)

# ---- smoke test: 3 videos, automatic checks ----
smoke = [items[0], items[1500], items[4500]]          # CCD crash, CCD normal, DoTA positive
open("/kaggle/tmp/smoke.txt", "w").write("\n".join(f"{v} {p}" for v, p in smoke))
t = time.time()
p = run("/kaggle/tmp/smoke.txt", 0, 1, 0, "/kaggle/working/smoke.log"); p.wait()
print(open("/kaggle/working/smoke.log").read()[-1500:], flush=True)
problems = []
for v, _ in smoke:
    f = os.path.join(OUT, v + ".npz")
    if not os.path.exists(f):
        problems.append(v + ": no output"); continue
    z = np.load(f)
    if z["det"].shape != (50, 19, 8): problems.append(v + f": det shape {z['det'].shape}")
    if z["det"][..., 7].sum() == 0: problems.append(v + ": no detections")
    if (z["labels"] == 0).mean() < 0.01: problems.append(v + ": no road pixels")
    if not np.isfinite(z["ctx"].astype(float)).all(): problems.append(v + ": non-finite context")
sec = (time.time() - t) / 3
est_h = sec * len(items) / ngpu / 3600
smoke_res = dict(problems=problems, sec_per_video=round(sec, 1), est_full_hours=round(est_h, 2), gpus=ngpu)
json.dump(smoke_res, open("/kaggle/working/smoke_result.json", "w"), indent=1)
print("SMOKE", smoke_res, flush=True)
if problems:
    sys.exit("smoke test failed; full extraction not started")

# ---- full extraction on every GPU ----
procs = [run("/kaggle/tmp/all.txt", i, ngpu, i, f"/kaggle/working/extract_gpu{i}.log") for i in range(ngpu)]
for p in procs: p.wait()
for i in range(ngpu):
    print("".join(open(f"/kaggle/working/extract_gpu{i}.log").readlines()[-6:]), flush=True)
have = {os.path.basename(f)[:-4] for f in glob.glob(OUT + "/*.npz")}
missing = [v for v, _ in items if v not in have]
json.dump(dict(done=len(items) - len(missing), wanted=len(items), missing=missing[:50], n_missing=len(missing),
               elapsed_h=round((time.time() - T0) / 3600, 2), commit="6543fce", smoke=smoke_res),
          open("/kaggle/working/EXTRACT_STATUS.json", "w"), indent=1)
print("done", len(items) - len(missing), "/", len(items), flush=True)
